-- Technical sponsor equipment catalogue, extended loadouts and condition/wear engine

-- Add four more regional brands so the pool includes South America and Africa.
insert into public.technical_sponsor_brands(
  code,name,country_code,region,tier,prestige,budget_level,target_rank_best,target_rank_worst,min_reputation,
  contract_strength,discount_min_pct,discount_max_pct,free_equipment_min,free_equipment_max,free_replacements,
  maintenance_discount_min_pct,maintenance_discount_max_pct,contract_weeks_min,contract_weeks_max,generosity,
  rarity_weight,offer_probability,target_player_level,philosophy,price_level,primary_color,secondary_color,logo_variant
) values
('OLYMPIKOS','Olympikos','BR','South America','established',55,3,120,2200,24,52,12,26,1,3,false,10,22,20,40,64,0.95,0.078,'Developing professionals / tour regulars','durable South American court footwear','mid-range','hsl(166 70% 35%)','hsl(42 82% 52%)',3),
('PENALTI','Penalti','BR','South America','entry',34,2,450,5000,10,34,6,15,0,2,false,0,10,12,26,62,1.25,0.098,'Juniors / lower-ranked professionals','accessible warm-weather match clothing','value','hsl(26 78% 45%)','hsl(216 70% 45%)',5),
('RAINYA','Rainya','BR','South America','established',49,2,180,2800,20,45,10,22,1,3,false,8,18,20,36,66,1.05,0.085,'Developing professionals / tour regulars','classic Brazilian court apparel','mid-range','hsl(306 64% 42%)','hsl(76 72% 44%)',7),
('BATHOO','Bathoo','ZA','Africa','entry',31,2,500,5000,8,32,5,14,0,2,false,0,10,12,24,67,1.30,0.102,'Juniors / lower-ranked professionals','value-focused cushioned performance footwear','value','hsl(204 72% 38%)','hsl(12 74% 54%)',2)
on conflict(code) do update set
 name=excluded.name,country_code=excluded.country_code,region=excluded.region,tier=excluded.tier,prestige=excluded.prestige,
 budget_level=excluded.budget_level,target_rank_best=excluded.target_rank_best,target_rank_worst=excluded.target_rank_worst,
 min_reputation=excluded.min_reputation,contract_strength=excluded.contract_strength,discount_min_pct=excluded.discount_min_pct,
 discount_max_pct=excluded.discount_max_pct,free_equipment_min=excluded.free_equipment_min,free_equipment_max=excluded.free_equipment_max,
 free_replacements=excluded.free_replacements,maintenance_discount_min_pct=excluded.maintenance_discount_min_pct,
 maintenance_discount_max_pct=excluded.maintenance_discount_max_pct,contract_weeks_min=excluded.contract_weeks_min,
 contract_weeks_max=excluded.contract_weeks_max,generosity=excluded.generosity,rarity_weight=excluded.rarity_weight,
 offer_probability=excluded.offer_probability,target_player_level=excluded.target_player_level,philosophy=excluded.philosophy,
 price_level=excluded.price_level,primary_color=excluded.primary_color,secondary_color=excluded.secondary_color,
 logo_variant=excluded.logo_variant,is_active=true,updated_at=now();

update public.technical_sponsor_brands
set logo_url=public.make_technical_brand_logo_v1(name,primary_color,secondary_color,logo_variant),updated_at=now()
where code in ('OLYMPIKOS','PENALTI','RAINYA','BATHOO');

insert into public.technical_sponsor_brand_categories(brand_id,category,is_primary,product_count_target,identity_profile) values
((select id from public.technical_sponsor_brands where code='OLYMPIKOS'),'shoes',true,4,'durable South American court footwear; all-court and surface-specialist models'),
((select id from public.technical_sponsor_brands where code='PENALTI'),'apparel',true,4,'accessible warm-weather match clothing; unified clothing collections'),
((select id from public.technical_sponsor_brands where code='RAINYA'),'apparel',true,4,'classic Brazilian court apparel; unified clothing collections'),
((select id from public.technical_sponsor_brands where code='BATHOO'),'shoes',true,4,'value-focused cushioned performance footwear; all-court and surface-specialist models')
on conflict(brand_id,category) do update set is_primary=excluded.is_primary,product_count_target=excluded.product_count_target,identity_profile=excluded.identity_profile;

alter table public.equipment_catalog_items
  add column if not exists technical_brand_id uuid references public.technical_sponsor_brands(id) on delete restrict,
  add column if not exists product_profile text not null default 'standard',
  add column if not exists gameplay_effects jsonb not null default '{}'::jsonb,
  add column if not exists wear_per_match numeric(5,2) not null default 1.00,
  add column if not exists wrong_surface_wear_multiplier numeric(5,2) not null default 1.00,
  add column if not exists weather_profile text,
  add column if not exists accessory_kind text,
  add column if not exists estimated_uses smallint;

alter table public.equipment_catalog_items drop constraint if exists equipment_catalog_items_equip_slot_check;
alter table public.equipment_catalog_items add constraint equipment_catalog_items_equip_slot_check
  check (equip_slot is null or equip_slot in ('racket','string','shoes','apparel','accessory'));
alter table public.equipment_catalog_items drop constraint if exists equipment_catalog_items_weather_profile_check;
alter table public.equipment_catalog_items add constraint equipment_catalog_items_weather_profile_check
  check (weather_profile is null or weather_profile in ('all','hot','cool','wet','windy'));
alter table public.equipment_catalog_items drop constraint if exists equipment_catalog_items_accessory_kind_check;
alter table public.equipment_catalog_items add constraint equipment_catalog_items_accessory_kind_check
  check ((item_type='accessory' and accessory_kind in ('bag','cap','towel','bottle','dampener','overgrip','wristband')) or (item_type<>'accessory' and accessory_kind is null));
alter table public.equipment_catalog_items drop constraint if exists equipment_catalog_items_wear_per_match_check;
alter table public.equipment_catalog_items add constraint equipment_catalog_items_wear_per_match_check check (wear_per_match > 0 and wear_per_match <= 100);
alter table public.equipment_catalog_items drop constraint if exists equipment_catalog_items_wrong_surface_wear_multiplier_check;
alter table public.equipment_catalog_items add constraint equipment_catalog_items_wrong_surface_wear_multiplier_check check (wrong_surface_wear_multiplier >= 1 and wrong_surface_wear_multiplier <= 4);
alter table public.equipment_catalog_items drop constraint if exists equipment_catalog_items_estimated_uses_check;
alter table public.equipment_catalog_items add constraint equipment_catalog_items_estimated_uses_check check (estimated_uses is null or estimated_uses between 1 and 500);

create index if not exists equipment_catalog_items_technical_brand_idx on public.equipment_catalog_items(technical_brand_id,item_type,is_active);
create index if not exists player_equipment_inventory_catalog_item_idx on public.player_equipment_inventory(catalog_item_id);

alter table public.player_equipment_inventory alter column condition type numeric(5,2) using condition::numeric(5,2);
alter table public.player_equipment_wear_events
  alter column racket_before type numeric(5,2) using racket_before::numeric(5,2),
  alter column racket_after type numeric(5,2) using racket_after::numeric(5,2),
  alter column string_before type numeric(5,2) using string_before::numeric(5,2),
  alter column string_after type numeric(5,2) using string_after::numeric(5,2),
  alter column shoes_before type numeric(5,2) using shoes_before::numeric(5,2),
  alter column shoes_after type numeric(5,2) using shoes_after::numeric(5,2),
  add column if not exists apparel_before numeric(5,2),
  add column if not exists apparel_after numeric(5,2),
  add column if not exists accessories_before jsonb not null default '{}'::jsonb,
  add column if not exists accessories_after jsonb not null default '{}'::jsonb;

alter table public.player_equipment_loadouts add column if not exists apparel_inventory_id uuid references public.player_equipment_inventory(id) on delete set null;
create index if not exists player_equipment_loadouts_racket_inventory_idx on public.player_equipment_loadouts(racket_inventory_id);
create index if not exists player_equipment_loadouts_shoes_inventory_idx on public.player_equipment_loadouts(shoes_inventory_id);
create index if not exists player_equipment_loadouts_string_inventory_idx on public.player_equipment_loadouts(string_inventory_id);
create index if not exists player_equipment_loadouts_apparel_inventory_idx on public.player_equipment_loadouts(apparel_inventory_id);
create index if not exists player_equipment_wear_events_match_idx on public.player_equipment_wear_events(match_id);

create table if not exists public.player_equipment_accessory_loadout (
  player_id uuid not null references public.players(id) on delete cascade,
  accessory_kind text not null check (accessory_kind in ('bag','cap','towel','bottle','dampener','overgrip','wristband')),
  inventory_id uuid not null unique references public.player_equipment_inventory(id) on delete cascade,
  updated_at timestamptz not null default now(),
  primary key (player_id,accessory_kind)
);
alter table public.player_equipment_accessory_loadout enable row level security;
drop policy if exists player_equipment_accessory_loadout_owner_read on public.player_equipment_accessory_loadout;
create policy player_equipment_accessory_loadout_owner_read on public.player_equipment_accessory_loadout for select to authenticated using (exists (select 1 from public.players p where p.id=player_id and p.owner_user_id=(select auth.uid())));
revoke all on public.player_equipment_accessory_loadout from anon,authenticated;
grant select on public.player_equipment_accessory_loadout to authenticated;

create or replace function public.equipment_condition_factor_v1(p_condition numeric) returns numeric language sql immutable set search_path='public' as $$
  select round(greatest(0.35::numeric,least(1.0::numeric,0.35 + 0.65*(least(100::numeric,greatest(0::numeric,coalesce(p_condition,0)))/100.0))),4);
$$;
revoke all on function public.equipment_condition_factor_v1(numeric) from public,anon,authenticated;

create or replace function public.scale_equipment_effects_v1(p_effects jsonb,p_condition numeric) returns jsonb language sql immutable set search_path='public' as $$
  select coalesce(jsonb_object_agg(e.key,to_jsonb(round((e.value#>>'{}')::numeric*public.equipment_condition_factor_v1(p_condition),2))),'{}'::jsonb)
  from jsonb_each(coalesce(p_effects,'{}'::jsonb)) e where jsonb_typeof(e.value)='number';
$$;
revoke all on function public.scale_equipment_effects_v1(jsonb,numeric) from public,anon,authenticated;

create or replace function public.calculate_equipment_resale_value_v1(p_purchase_price bigint,p_condition numeric,p_resale_modifier numeric) returns bigint language sql immutable set search_path='public' as $$
  select greatest(0::bigint,floor(greatest(coalesce(p_purchase_price,0),0)::numeric*0.65*(least(greatest(coalesce(p_condition,0),0),100)/100.0)*least(greatest(coalesce(p_resale_modifier,0),0),1))::bigint);
$$;
create or replace function public.calculate_equipment_resale_value_v1(p_purchase_price bigint,p_condition smallint,p_resale_modifier numeric) returns bigint language sql immutable set search_path='public' as $$
  select public.calculate_equipment_resale_value_v1(p_purchase_price,p_condition::numeric,p_resale_modifier);
$$;

create or replace function public.equipment_line_name_v1(p_code text) returns text language sql immutable set search_path='public' as $$
  select (array['Apex','Vector','Pulse','Vertex','Nova','Arc','Drive','Core','Tour','Pro','Velocity','Orbit','Strike','Elite','Flux','Prime','Motion','Edge','Zenith','Vantage'])[mod(abs(hashtext(coalesce(p_code,''))::bigint),20)::int+1];
$$;
revoke all on function public.equipment_line_name_v1(text) from public,anon,authenticated;

create or replace function public.make_equipment_item_image_v1(p_item_type text,p_accessory_kind text,p_brand text,p_model text,p_primary text,p_secondary text,p_variant integer) returns text language plpgsql immutable set search_path='public' as $$
declare b text:=replace(replace(replace(coalesce(p_brand,'Brand'),'&','&amp;'),'<','&lt;'),'>','&gt;'); m text:=replace(replace(replace(coalesce(p_model,'Model'),'&','&amp;'),'<','&lt;'),'>','&gt;'); shape text; svg text;
begin
  if p_item_type='racket' then shape:=format('<g transform="translate(175 38) rotate(%s 120 145)"><ellipse cx="120" cy="112" rx="78" ry="96" fill="white" stroke="%s" stroke-width="15"/><ellipse cx="120" cy="112" rx="61" ry="78" fill="none" stroke="%s" stroke-width="2" opacity=".55"/><path d="M61 76 H179 M54 100 H186 M52 124 H188 M58 148 H182 M79 36 V187 M99 22 V202 M120 16 V208 M141 22 V202 M161 36 V187" stroke="%s" stroke-width="2" opacity=".40"/><path d="M100 198 L140 198 L132 292 L108 292 Z" fill="%s"/><rect x="105" y="274" width="30" height="94" rx="10" fill="#263743"/></g>',((coalesce(p_variant,1)%5)-2)*2,p_primary,p_secondary,p_secondary,p_primary);
  elsif p_item_type='shoes' then shape:=format('<g transform="translate(86 110)"><path d="M16 116 C80 108 126 70 159 23 C188 60 224 92 317 110 L339 151 C269 176 92 179 26 157 Z" fill="%s"/><path d="M80 116 C132 105 171 79 194 55 L238 92 L291 116" fill="none" stroke="%s" stroke-width="14" stroke-linecap="round"/><path d="M34 151 H330" stroke="#263743" stroke-width="11" stroke-linecap="round"/><path d="M147 85 L180 111 M171 67 L205 96 M197 62 L226 86" stroke="white" stroke-width="5" stroke-linecap="round"/></g>',p_primary,p_secondary);
  elsif p_item_type='apparel' then shape:=format('<g transform="translate(120 52)"><path d="M102 20 L160 20 L199 47 L252 83 L222 132 L187 113 L187 306 L75 306 L75 113 L40 132 L10 83 L63 47 Z" fill="%s"/><path d="M101 20 Q131 67 161 20" fill="white" opacity=".95"/><path d="M75 158 H187" stroke="%s" stroke-width="12" opacity=".85"/><path d="M92 65 H170" stroke="white" stroke-width="5" opacity=".6"/></g>',p_primary,p_secondary);
  else shape:=case coalesce(p_accessory_kind,'bag')
      when 'bag' then format('<g transform="translate(104 90)"><rect x="30" y="54" width="280" height="184" rx="44" fill="%s"/><path d="M92 60 Q170 -20 248 60" fill="none" stroke="%s" stroke-width="18"/><path d="M170 54 V238" stroke="white" stroke-width="6" opacity=".55"/><circle cx="170" cy="144" r="28" fill="%s"/></g>',p_primary,p_secondary,p_secondary)
      when 'cap' then format('<g transform="translate(104 110)"><path d="M56 118 Q70 20 176 20 Q280 28 288 126 Q189 91 56 118 Z" fill="%s"/><path d="M146 120 Q280 102 350 147 Q270 176 164 153 Z" fill="%s"/></g>',p_primary,p_secondary)
      when 'towel' then format('<g transform="translate(145 72) rotate(-7 130 140)"><rect x="30" y="20" width="230" height="290" rx="20" fill="%s"/><path d="M55 78 H235 M55 119 H235 M55 160 H235 M55 201 H235" stroke="%s" stroke-width="8" opacity=".55"/></g>',p_primary,p_secondary)
      when 'bottle' then format('<g transform="translate(195 52)"><rect x="72" y="13" width="74" height="42" rx="10" fill="%s"/><path d="M55 58 Q55 40 75 40 H143 Q163 40 163 58 L178 293 Q180 322 151 322 H67 Q38 322 40 293 Z" fill="%s"/><path d="M64 145 H153" stroke="white" stroke-width="15" opacity=".65"/></g>',p_secondary,p_primary)
      when 'dampener' then format('<g transform="translate(188 105)"><circle cx="100" cy="100" r="83" fill="%s"/><circle cx="100" cy="100" r="42" fill="%s"/><path d="M100 20 V180 M20 100 H180" stroke="white" stroke-width="10" opacity=".55"/></g>',p_primary,p_secondary)
      when 'overgrip' then format('<g transform="translate(190 52) rotate(16 90 150)"><rect x="60" y="10" width="70" height="310" rx="30" fill="%s"/><path d="M62 60 L128 32 M62 110 L128 82 M62 160 L128 132 M62 210 L128 182 M62 260 L128 232" stroke="%s" stroke-width="10"/></g>',p_primary,p_secondary)
      else format('<g transform="translate(152 92)"><path d="M45 24 Q132 -16 219 24 L202 103 Q132 74 62 103 Z" fill="%s"/><path d="M62 150 Q132 121 202 150 L219 229 Q132 269 45 229 Z" fill="%s"/></g>',p_primary,p_secondary) end;
  end if;
  svg:=format('<svg xmlns="http://www.w3.org/2000/svg" width="600" height="420" viewBox="0 0 600 420"><rect width="600" height="420" fill="white"/><circle cx="490" cy="72" r="108" fill="%s" opacity=".08"/>%s<text x="32" y="48" font-family="Arial,sans-serif" font-size="24" font-weight="900" fill="#17344b">%s</text><text x="32" y="76" font-family="Arial,sans-serif" font-size="15" font-weight="700" fill="#708494">%s</text></svg>',p_secondary,shape,b,m);
  return 'data:image/svg+xml;base64,'||encode(convert_to(svg,'UTF8'),'base64');
end; $$;
revoke all on function public.make_equipment_item_image_v1(text,text,text,text,text,text,integer) from public,anon,authenticated;

update public.equipment_catalog_items set availability_status='unavailable' where sku in ('RKT-VOLT-98','RKT-AXIOM-97','RKT-SPIN-100','SHO-HARD-PRO','SHO-CLAY-PRO','SHO-GRASS-PRO');
update public.equipment_catalog_items set availability_status='unavailable',is_resellable=false,product_profile='starter',wear_per_match=case when item_type='racket' then 1.50 else 3.20 end,wrong_surface_wear_multiplier=case when item_type='shoes' then 1.60 else 1.00 end,estimated_uses=case when item_type='racket' then 67 else 31 end where sku in ('RKT-START-100','SHO-ALL-COURT');

insert into public.equipment_catalog_items(sku,item_type,brand,model,description,price_usd,tier,surface,power,control,spin,comfort,traction,stability,durability,sort_order,is_active,image_url,tags,advantages,disadvantages,maintenance_text,lifespan_text,effect_scope,availability_status,equip_slot,is_resellable,resale_modifier,product_profile,gameplay_effects,wear_per_match,wrong_surface_wear_multiplier,weather_profile,accessory_kind,estimated_uses) values
('APP-START-CORE','apparel','Courtline','Starter Match Kit','A simple all-weather starter match outfit with neutral comfort and no specialist advantage.',45,1,null,75,75,75,76,75,75,74,1,true,public.make_equipment_item_image_v1('apparel',null,'Courtline','Starter Match Kit','hsl(205 48% 42%)','hsl(205 18% 74%)',1),array['starter','all-weather','balanced'],array['Reliable basic match comfort'],array['No specialist weather advantage'],'Wash after competition use and replace when fabric condition becomes poor.','Approximately 65-75 matches under normal use.','match','unavailable','apparel',false,0.45,'starter',jsonb_build_object('comfort_pct',0.12),1.50,1.00,'all',null,67),
('ACC-START-TOWEL','accessory','Courtline','Starter Court Towel','A basic courtside towel that provides a very small focus and comfort benefit during matches.',12,1,null,75,75,75,76,75,75,65,2,true,public.make_equipment_item_image_v1('accessory','towel','Courtline','Starter Court Towel','hsl(192 44% 52%)','hsl(206 18% 80%)',2),array['starter','towel','comfort'],array['Small comfort support'],array['Wears faster than bags and caps'],'Wash and dry after use. Replace when absorbency and condition become poor.','Approximately 30-35 matches under normal use.','match','unavailable','accessory',false,0.35,'towel',jsonb_build_object('comfort_pct',0.08,'focus_pct',0.08),3.00,1.00,'all','towel',34)
on conflict(sku) do update set description=excluded.description,price_usd=excluded.price_usd,tier=excluded.tier,image_url=excluded.image_url,tags=excluded.tags,advantages=excluded.advantages,disadvantages=excluded.disadvantages,maintenance_text=excluded.maintenance_text,lifespan_text=excluded.lifespan_text,effect_scope=excluded.effect_scope,availability_status=excluded.availability_status,equip_slot=excluded.equip_slot,is_resellable=excluded.is_resellable,resale_modifier=excluded.resale_modifier,product_profile=excluded.product_profile,gameplay_effects=excluded.gameplay_effects,wear_per_match=excluded.wear_per_match,wrong_surface_wear_multiplier=excluded.wrong_surface_wear_multiplier,weather_profile=excluded.weather_profile,accessory_kind=excluded.accessory_kind,estimated_uses=excluded.estimated_uses,is_active=true;

with src as (
 select b.id brand_id,b.code,b.name,b.tier sponsor_tier,b.prestige,b.primary_color,b.secondary_color,b.logo_variant,public.equipment_line_name_v1(b.code) line,gs n,case b.tier when 'entry' then 1 when 'established' then 2 when 'premium' then 3 else 4 end base_tier,case b.tier when 'entry' then -5 when 'established' then -2 when 'premium' then 2 else 5 end q,case b.tier when 'entry' then .78 when 'established' then .90 when 'premium' then 1.00 else 1.15 end fx
 from public.technical_sponsor_brands b join public.technical_sponsor_brand_categories bc on bc.brand_id=b.id and bc.category='racket' cross join lateral generate_series(1,bc.product_count_target) gs where b.is_active
), r as (
 select *,greatest(1,least(5,base_tier+case when n=1 then -1 when n=5 then 1 else 0 end))::smallint product_tier,case n when 1 then line||' Balance 100' when 2 then line||' Strike 98' when 3 then line||' Control 97' when 4 then line||' Spin 100' else line||' Precision 95' end model,case n when 1 then 'balanced' when 2 then 'power' when 3 then 'control' when 4 then 'spin' else 'precision' end profile from src
)
insert into public.equipment_catalog_items(sku,item_type,brand,model,description,price_usd,tier,surface,power,control,spin,comfort,traction,stability,durability,sort_order,is_active,image_url,tags,advantages,disadvantages,maintenance_text,lifespan_text,effect_scope,availability_status,equip_slot,is_resellable,resale_modifier,technical_brand_id,product_profile,gameplay_effects,wear_per_match,wrong_surface_wear_multiplier,weather_profile,accessory_kind,estimated_uses)
select 'RKT-'||code||'-'||lpad(n::text,2,'0'),'racket',name,model,name||' '||model||' is a '||profile||'-oriented racquet built around the brand''s '||(select philosophy from public.technical_sponsor_brands x where x.id=brand_id)||' identity.',(100+product_tier*55+n*13)::bigint,product_tier,null,
greatest(0,least(100,(case n when 1 then 80 when 2 then 89 when 3 then 74 when 4 then 83 else 79 end)+q))::smallint,greatest(0,least(100,(case n when 1 then 80 when 2 then 75 when 3 then 91 when 4 then 78 else 93 end)+q))::smallint,greatest(0,least(100,(case n when 1 then 79 when 2 then 81 when 3 then 76 when 4 then 92 else 82 end)+q))::smallint,greatest(0,least(100,(case n when 1 then 81 when 2 then 74 when 3 then 84 when 4 then 77 else 82 end)+q))::smallint,75,75,greatest(0,least(100,(case n when 1 then 82 when 2 then 77 when 3 then 85 when 4 then 79 else 88 end)+q))::smallint,(1000+row_number() over(order by prestige desc,code,n))::smallint,true,public.make_equipment_item_image_v1('racket',null,name,model,primary_color,secondary_color,logo_variant+n),array[profile,'racquet',case when n in (2,4) then 'aggressive' when n in (3,5) then 'precision' else 'all-court' end],
case n when 1 then array['Balanced response from both wings','Forgiving all-round setup'] when 2 then array['Extra serve and forehand power','Fast attacking response'] when 3 then array['Excellent directional control','Strong return and backhand stability'] when 4 then array['High spin production','Strong baseline rally support'] else array['Precision on return and at net','Premium directional feel'] end,
case n when 1 then array['No dominant specialist strength'] when 2 then array['Less forgiving on defensive returns','Slightly lower comfort'] when 3 then array['Less free power'] when 4 then array['Slightly reduced comfort on flat hitting'] else array['Rewards clean timing more than raw power'] end,'Inspect frame and grip regularly. Replace once condition becomes poor; no separate string category is required.','Approximately '||round(100/(case sponsor_tier when 'elite' then 1.30 when 'premium' then 1.40 when 'established' then 1.50 else 1.60 end))::int||' matches under normal use.','match','available','racket',true,0.88,brand_id,profile,
