select 'ACC-'||code||'-'||lpad(n::text,2,'0'),'accessory',name,model,name||' '||model||' is a '||kind||' accessory with a small, focused support benefit and its own condition lifecycle.',(case kind when 'bag' then 70 when 'cap' then 24 when 'towel' then 18 when 'bottle' then 22 when 'dampener' then 12 when 'overgrip' then 10 else 16 end+product_tier*case when kind='bag' then 14 else 4 end)::bigint,product_tier,null,75,75,75,greatest(0,least(100,(case kind when 'bag' then 78 when 'cap' then 82 when 'towel' then 78 when 'bottle' then 80 when 'dampener' then 84 when 'overgrip' then 80 else 82 end)+q))::smallint,75,75,greatest(0,least(100,(case kind when 'bag' then 94 when 'cap' then 90 when 'towel' then 72 when 'bottle' then 62 when 'dampener' then 79 when 'overgrip' then 68 else 84 end)+q))::smallint,(7000+row_number() over(order by prestige desc,code,n))::smallint,true,public.make_equipment_item_image_v1('accessory',kind,name,model,primary_color,secondary_color,logo_variant+n),array['accessory',kind,case when kind in ('bag','cap') then 'long-life' else 'match-support' end],case kind when 'bag' then array['Protects the equipped racquet from wear','Very long accessory life'] when 'cap' then array['Small hot-weather comfort support','Long-lasting accessory'] when 'towel' then array['Small focus and comfort support'] when 'bottle' then array['Small stamina support during matches'] when 'dampener' then array['Small comfort and control support'] when 'overgrip' then array['Small control and return support'] else array['Small comfort and focus support'] end,case kind when 'bag' then array['Higher purchase price than small accessories'] when 'cap' then array['Limited benefit outside warm conditions'] when 'towel' then array['Needs frequent replacement'] when 'bottle' then array['Short usable life: roughly eight matches'] when 'dampener' then array['Very small direct performance impact'] when 'overgrip' then array['Wears quickly under match use'] else array['Small specialist benefit only'] end,case kind when 'bag' then 'Keep dry and inspect zips/straps. Its protective benefit falls with condition.' when 'cap' then 'Wash gently and replace when shape or fabric condition is poor.' when 'towel' then 'Wash and dry after every match. Replace when absorbency falls.' when 'bottle' then 'Clean after every use. This consumable-style item is balanced around about eight uses.' when 'dampener' then 'Inspect for cracks or loss of elasticity.' when 'overgrip' then 'Replace regularly once tack and condition drop.' else 'Wash after play and replace when fabric elasticity declines.' end,'Approximately '||greatest(1,round(100/wear)::int)||' match uses under normal conditions.','match','available','accessory',true,0.58,brand_id,kind,case kind when 'bag' then jsonb_build_object('racket_wear_reduction_pct',round((10+product_tier*2.5)*fx,2)) when 'cap' then jsonb_build_object('comfort_pct',round(.16*fx,2),'focus_pct',round(.08*fx,2),'heat_resistance_pct',round(.36*fx,2)) when 'towel' then jsonb_build_object('comfort_pct',round(.14*fx,2),'focus_pct',round(.16*fx,2)) when 'bottle' then jsonb_build_object('stamina_pct',round(.34*fx,2),'comfort_pct',round(.08*fx,2)) when 'dampener' then jsonb_build_object('comfort_pct',round(.26*fx,2),'control_pct',round(.12*fx,2)) when 'overgrip' then jsonb_build_object('control_pct',round(.22*fx,2),'return_pct',round(.12*fx,2),'comfort_pct',round(.08*fx,2)) else jsonb_build_object('comfort_pct',round(.16*fx,2),'focus_pct',round(.13*fx,2)) end,wear,1.00,case when kind='cap' then 'hot' else 'all' end,kind,greatest(1,round(100/wear)::int)::smallint from z
