create or replace function public.initialize_player_equipment_v1(p_player_id uuid) returns void language plpgsql security definer set search_path='public' as $$
declare v_abs integer;v_racket uuid;v_shoes uuid;v_apparel uuid;v_accessory uuid;
begin
 if not exists(select 1 from public.players p where p.id=p_player_id and p.owner_user_id is not null) then return; end if;
 select public.game_day_absolute_v1(d.season,d.month,d.day) into v_abs from public.get_current_game_day_internal_v1() d;
 insert into public.player_equipment_loadouts(player_id) values(p_player_id) on conflict(player_id) do nothing;
 insert into public.player_equipment_inventory(id,player_id,catalog_item_id,condition,acquired_absolute_day,acquired_source)
 select gen_random_uuid(),p_player_id,c.id,100,v_abs,'starter' from public.equipment_catalog_items c where c.sku in ('RKT-START-100','SHO-ALL-COURT','APP-START-CORE','ACC-START-TOWEL') and c.is_active and not exists(select 1 from public.player_equipment_inventory i where i.player_id=p_player_id and i.catalog_item_id=c.id and i.acquired_source='starter');
 select i.id into v_racket from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.player_id=p_player_id and c.sku='RKT-START-100' order by i.created_at limit 1;
 select i.id into v_shoes from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.player_id=p_player_id and c.sku='SHO-ALL-COURT' order by i.created_at limit 1;
 select i.id into v_apparel from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.player_id=p_player_id and c.sku='APP-START-CORE' order by i.created_at limit 1;
 select i.id into v_accessory from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.player_id=p_player_id and c.sku='ACC-START-TOWEL' order by i.created_at limit 1;
 update public.player_equipment_loadouts set racket_inventory_id=coalesce(racket_inventory_id,v_racket),string_inventory_id=null,shoes_inventory_id=coalesce(shoes_inventory_id,v_shoes),apparel_inventory_id=coalesce(apparel_inventory_id,v_apparel),updated_at=now() where player_id=p_player_id;
 if v_accessory is not null then insert into public.player_equipment_accessory_loadout(player_id,accessory_kind,inventory_id) values(p_player_id,'towel',v_accessory) on conflict(player_id,accessory_kind) do nothing; end if;
end; $$;
revoke all on function public.initialize_player_equipment_v1(uuid) from public,anon,authenticated;

create or replace function public.equip_equipment_item_v1(p_inventory_id uuid) returns jsonb language plpgsql security definer set search_path='public' as $$
declare v_player uuid;v_type text;v_kind text;
begin
 select p.id into v_player from public.players p where p.owner_user_id=auth.uid() order by p.created_at desc limit 1;if v_player is null then raise exception 'Player not found.';end if;
 perform public.initialize_player_equipment_v1(v_player);
 select c.item_type,c.accessory_kind into v_type,v_kind from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.id=p_inventory_id and i.player_id=v_player and c.is_active;
 if v_type is null then raise exception 'Equipment item not owned or no longer active.';end if;
 if v_type='racket' then update public.player_equipment_loadouts set racket_inventory_id=p_inventory_id,updated_at=now() where player_id=v_player;
 elsif v_type='shoes' then update public.player_equipment_loadouts set shoes_inventory_id=p_inventory_id,updated_at=now() where player_id=v_player;
 elsif v_type='apparel' then update public.player_equipment_loadouts set apparel_inventory_id=p_inventory_id,apparel_brand=(select brand from public.equipment_catalog_items c join public.player_equipment_inventory i on i.catalog_item_id=c.id where i.id=p_inventory_id),updated_at=now() where player_id=v_player;
 elsif v_type='accessory' then if v_kind is null then raise exception 'Accessory kind is not configured.';end if;insert into public.player_equipment_accessory_loadout(player_id,accessory_kind,inventory_id,updated_at) values(v_player,v_kind,p_inventory_id,now()) on conflict(player_id,accessory_kind) do update set inventory_id=excluded.inventory_id,updated_at=now();
 else raise exception 'This equipment type does not use an active equipment slot.';end if;
 return jsonb_build_object('status','equipped','inventory_id',p_inventory_id,'item_type',v_type,'accessory_kind',v_kind);
end; $$;
revoke all on function public.equip_equipment_item_v1(uuid) from public,anon;grant execute on function public.equip_equipment_item_v1(uuid) to authenticated;

create or replace function public.get_equipment_match_modifiers_readonly_v2(p_player_id uuid,p_surface text default 'hard') returns jsonb language plpgsql stable security definer set search_path='public' as $$
declare l public.player_equipment_loadouts%rowtype;r record;sh record;ap record;v_surface text:=lower(coalesce(p_surface,'hard'));fr numeric:=0;fs numeric:=0;fa numeric:=0;surface_bonus numeric:=0;acc_serve numeric:=0;acc_return numeric:=0;acc_rally numeric:=0;acc_net numeric:=0;acc_move numeric:=0;acc_comfort numeric:=0;acc_stamina numeric:=0;acc_focus numeric:=0;acc_heat numeric:=0;acc_cold numeric:=0;acc_power numeric:=0;acc_control numeric:=0;acc_spin numeric:=0;bag_protect numeric:=0;acc_count integer:=0;v_power numeric:=0;v_control numeric:=0;v_spin numeric:=0;v_movement numeric:=0;v_comfort numeric:=0;v_serve numeric:=0;v_return numeric:=0;v_rally numeric:=0;v_net numeric:=0;v_stamina numeric:=0;v_focus numeric:=0;v_heat numeric:=0;v_cold numeric:=0;
begin
 select * into l from public.player_equipment_loadouts where player_id=p_player_id;
 if l.player_id is null then return jsonb_build_object('surface',v_surface,'power_pct',0,'control_pct',0,'spin_pct',0,'movement_pct',0,'comfort_pct',0,'serve_pct',0,'return_pct',0,'rally_pct',0,'net_pct',0,'stamina_pct',0,'focus_pct',0,'heat_resistance_pct',0,'cold_resistance_pct',0,'racket_wear_reduction_pct',0,'racket_condition',0,'shoes_condition',0,'apparel_condition',0,'accessory_count',0,'shoe_surface','all');end if;
 select i.condition,c.* into r from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.id=l.racket_inventory_id and i.player_id=p_player_id;
 select i.condition,c.* into sh from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.id=l.shoes_inventory_id and i.player_id=p_player_id;
 select i.condition,c.* into ap from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.id=l.apparel_inventory_id and i.player_id=p_player_id;
 fr:=case when r.condition is null then 0 else public.equipment_condition_factor_v1(r.condition) end;fs:=case when sh.condition is null then 0 else public.equipment_condition_factor_v1(sh.condition) end;fa:=case when ap.condition is null then 0 else public.equipment_condition_factor_v1(ap.condition) end;
 select coalesce(sum(coalesce((c.gameplay_effects->>'serve_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'return_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'rally_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'net_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'movement_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'comfort_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'stamina_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'focus_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'heat_resistance_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'cold_resistance_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'power_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'control_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(sum(coalesce((c.gameplay_effects->>'spin_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0),coalesce(max(case when c.accessory_kind='bag' then coalesce((c.gameplay_effects->>'racket_wear_reduction_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition) else 0 end),0),count(*)::integer into acc_serve,acc_return,acc_rally,acc_net,acc_move,acc_comfort,acc_stamina,acc_focus,acc_heat,acc_cold,acc_power,acc_control,acc_spin,bag_protect,acc_count from public.player_equipment_accessory_loadout al join public.player_equipment_inventory i on i.id=al.inventory_id and i.player_id=al.player_id join public.equipment_catalog_items c on c.id=i.catalog_item_id and c.is_active where al.player_id=p_player_id;
 surface_bonus:=case when sh.surface=v_surface then .45 when sh.surface='all' then .15 when sh.surface is null then 0 else -.45 end;
 v_power:=coalesce(((r.power-75)*.025)*fr,0)+coalesce((r.gameplay_effects->>'power_pct')::numeric,0)*fr+acc_power;v_control:=coalesce(((r.control-75)*.025)*fr,0)+coalesce((r.gameplay_effects->>'control_pct')::numeric,0)*fr+acc_control;v_spin:=coalesce(((r.spin-75)*.022)*fr,0)+coalesce((r.gameplay_effects->>'spin_pct')::numeric,0)*fr+acc_spin;v_movement:=coalesce((((sh.traction+sh.stability)/2.0-75)*.022)*fs,0)+surface_bonus+coalesce((sh.gameplay_effects->>'movement_pct')::numeric,0)*fs+coalesce((ap.gameplay_effects->>'movement_pct')::numeric,0)*fa+acc_move;v_comfort:=coalesce(((r.comfort-75)*.010)*fr,0)+coalesce(((sh.comfort-75)*.010)*fs,0)+coalesce(((ap.comfort-75)*.010)*fa,0)+coalesce((r.gameplay_effects->>'comfort_pct')::numeric,0)*fr+coalesce((sh.gameplay_effects->>'comfort_pct')::numeric,0)*fs+coalesce((ap.gameplay_effects->>'comfort_pct')::numeric,0)*fa+acc_comfort;
 v_serve:=coalesce((r.gameplay_effects->>'serve_pct')::numeric,0)*fr+coalesce((sh.gameplay_effects->>'serve_pct')::numeric,0)*fs+coalesce((ap.gameplay_effects->>'serve_pct')::numeric,0)*fa+acc_serve+v_power*.25;v_return:=coalesce((r.gameplay_effects->>'return_pct')::numeric,0)*fr+coalesce((sh.gameplay_effects->>'return_pct')::numeric,0)*fs+coalesce((ap.gameplay_effects->>'return_pct')::numeric,0)*fa+acc_return+v_control*.25+v_movement*.08;v_rally:=coalesce((r.gameplay_effects->>'rally_pct')::numeric,0)*fr+coalesce((sh.gameplay_effects->>'rally_pct')::numeric,0)*fs+coalesce((ap.gameplay_effects->>'rally_pct')::numeric,0)*fa+acc_rally+(v_power+v_control+v_spin)*.10+v_movement*.08;v_net:=coalesce((r.gameplay_effects->>'net_pct')::numeric,0)*fr+coalesce((sh.gameplay_effects->>'net_pct')::numeric,0)*fs+coalesce((ap.gameplay_effects->>'net_pct')::numeric,0)*fa+acc_net+v_control*.10+v_movement*.07;v_stamina:=coalesce((ap.gameplay_effects->>'stamina_pct')::numeric,0)*fa+coalesce((sh.gameplay_effects->>'stamina_pct')::numeric,0)*fs+acc_stamina;v_focus:=coalesce((ap.gameplay_effects->>'focus_pct')::numeric,0)*fa+acc_focus;v_heat:=coalesce((ap.gameplay_effects->>'heat_resistance_pct')::numeric,0)*fa+acc_heat;v_cold:=coalesce((ap.gameplay_effects->>'cold_resistance_pct')::numeric,0)*fa+acc_cold;
 return jsonb_build_object('surface',v_surface,'power_pct',round(greatest(-4,least(4,v_power)),2),'control_pct',round(greatest(-4,least(4,v_control)),2),'spin_pct',round(greatest(-4,least(4,v_spin)),2),'movement_pct',round(greatest(-4,least(4,v_movement)),2),'comfort_pct',round(greatest(-4,least(4,v_comfort)),2),'serve_pct',round(greatest(-4,least(4,v_serve)),2),'return_pct',round(greatest(-4,least(4,v_return)),2),'rally_pct',round(greatest(-4,least(4,v_rally)),2),'net_pct',round(greatest(-4,least(4,v_net)),2),'stamina_pct',round(greatest(-3,least(3,v_stamina)),2),'focus_pct',round(greatest(-3,least(3,v_focus)),2),'heat_resistance_pct',round(greatest(-3,least(3,v_heat)),2),'cold_resistance_pct',round(greatest(-3,least(3,v_cold)),2),'racket_wear_reduction_pct',round(greatest(0,least(35,bag_protect)),2),'racket_condition',coalesce(r.condition,0),'shoes_condition',coalesce(sh.condition,0),'apparel_condition',coalesce(ap.condition,0),'accessory_count',acc_count,'shoe_surface',coalesce(sh.surface,'all'));
end; $$;
revoke all on function public.get_equipment_match_modifiers_readonly_v2(uuid,text) from public,anon,authenticated;

create or replace function public.get_equipment_match_modifiers_internal_v1(p_player_id uuid,p_surface text default 'hard') returns jsonb language plpgsql security definer set search_path='public' as $$ begin perform public.initialize_player_equipment_v1(p_player_id);return public.get_equipment_match_modifiers_readonly_v2(p_player_id,p_surface);end; $$;
revoke all on function public.get_equipment_match_modifiers_internal_v1(uuid,text) from public,anon,authenticated;
create or replace function public.get_equipment_match_modifiers_v1(p_surface text default 'hard') returns jsonb language plpgsql security definer set search_path='public' as $$ declare v_player uuid;begin select p.id into v_player from public.players p where p.owner_user_id=auth.uid() order by p.created_at desc limit 1;if v_player is null then raise exception 'Player not found.';end if;return public.get_equipment_match_modifiers_internal_v1(v_player,p_surface);end; $$;
revoke all on function public.get_equipment_match_modifiers_v1(text) from public,anon;grant execute on function public.get_equipment_match_modifiers_v1(text) to authenticated;

create or replace function public.get_match_engine_profile_for_match_v2(p_player_id uuid,p_surface text,p_match_id uuid) returns jsonb language plpgsql stable security definer set search_path='public' as $$
declare b jsonb;e jsonb;eq jsonb;m numeric:=1;eq_serve numeric:=0;eq_return numeric:=0;eq_rally numeric:=0;eq_net numeric:=0;climate numeric:=0;temp numeric;eq_avg numeric:=0;
begin
 b:=public.get_match_engine_profile_for_match_base_v2(p_player_id,p_surface,p_match_id);eq:=public.get_equipment_match_modifiers_readonly_v2(p_player_id,p_surface);
 begin temp:=nullif(b->'weather'->>'temperature_c','')::numeric;exception when others then temp:=null;end;
 if temp is not null and temp>=28 then climate:=coalesce((eq->>'heat_resistance_pct')::numeric,0)*.35;elsif temp is not null and temp<=12 then climate:=coalesce((eq->>'cold_resistance_pct')::numeric,0)*.35;end if;
 eq_serve:=greatest(-4,least(4,coalesce((eq->>'serve_pct')::numeric,0)+coalesce((eq->>'focus_pct')::numeric,0)*.10));eq_return:=greatest(-4,least(4,coalesce((eq->>'return_pct')::numeric,0)+coalesce((eq->>'focus_pct')::numeric,0)*.12+climate));eq_rally:=greatest(-4,least(4,coalesce((eq->>'rally_pct')::numeric,0)+coalesce((eq->>'stamina_pct')::numeric,0)*.22+climate));eq_net:=greatest(-4,least(4,coalesce((eq->>'net_pct')::numeric,0)+coalesce((eq->>'focus_pct')::numeric,0)*.10));eq_avg:=(eq_serve+eq_return+eq_rally+eq_net)/4.0;
 b:=jsonb_set(b,'{ratings,serve}',to_jsonb(round((b->'ratings'->>'serve')::numeric*(1+eq_serve/100.0),2)));b:=jsonb_set(b,'{ratings,return}',to_jsonb(round((b->'ratings'->>'return')::numeric*(1+eq_return/100.0),2)));b:=jsonb_set(b,'{ratings,rally}',to_jsonb(round((b->'ratings'->>'rally')::numeric*(1+eq_rally/100.0),2)));b:=jsonb_set(b,'{ratings,net}',to_jsonb(round((b->'ratings'->>'net')::numeric*(1+eq_net/100.0),2)));b:=jsonb_set(b,'{ratings,effective_overall}',to_jsonb(round((b->'ratings'->>'effective_overall')::numeric*(1+eq_avg/100.0),2)));
 e:=public.get_player_staff_effects_v1(p_player_id);m:=greatest(1,least(1.02,coalesce((e->>'match_staff_multiplier')::numeric,1)));if m>1 then b:=jsonb_set(b,'{ratings,serve}',to_jsonb(round((b->'ratings'->>'serve')::numeric*m,2)));b:=jsonb_set(b,'{ratings,return}',to_jsonb(round((b->'ratings'->>'return')::numeric*m,2)));b:=jsonb_set(b,'{ratings,rally}',to_jsonb(round((b->'ratings'->>'rally')::numeric*m,2)));b:=jsonb_set(b,'{ratings,net}',to_jsonb(round((b->'ratings'->>'net')::numeric*m,2)));b:=jsonb_set(b,'{ratings,effective_overall}',to_jsonb(round((b->'ratings'->>'effective_overall')::numeric*m,2)));end if;
 return b||jsonb_build_object('equipment_support',eq||jsonb_build_object('effective_serve_pct',round(eq_serve,2),'effective_return_pct',round(eq_return,2),'effective_rally_pct',round(eq_rally,2),'effective_net_pct',round(eq_net,2),'climate_support_pct',round(climate,2)),'staff_support',jsonb_build_object('match_multiplier',round(m,4),'bonus_percent',round((m-1)*100,2),'global_cap_percent',2.0));
end; $$;

create or replace function public.apply_equipment_match_wear_v1(p_player_id uuid,p_match_id uuid,p_surface text) returns jsonb language plpgsql security definer set search_path='public' as $$
declare l public.player_equipment_loadouts%rowtype;rb numeric;ra numeric;shb numeric;sha numeric;apb numeric;apa numeric;rw numeric:=0;shw numeric:=0;apw numeric:=0;actual_rw numeric:=0;actual_shw numeric:=0;shoe_surface text;shoe_mult numeric:=1;bag_protect numeric:=0;a record;before_acc jsonb:='{}'::jsonb;after_acc jsonb:='{}'::jsonb;a_after numeric;v_surface text:=lower(coalesce(p_surface,'hard'));
begin
 if exists(select 1 from public.player_equipment_wear_events where player_id=p_player_id and match_id=p_match_id) then return jsonb_build_object('status','already_applied');end if;
 perform public.initialize_player_equipment_v1(p_player_id);select * into l from public.player_equipment_loadouts where player_id=p_player_id for update;if l.player_id is null then return jsonb_build_object('status','no_loadout');end if;
 select i.condition,c.wear_per_match into rb,rw from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.id=l.racket_inventory_id and i.player_id=p_player_id for update of i;
 select i.condition,c.wear_per_match,c.surface,c.wrong_surface_wear_multiplier into shb,shw,shoe_surface,shoe_mult from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.id=l.shoes_inventory_id and i.player_id=p_player_id for update of i;
 select i.condition,c.wear_per_match into apb,apw from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id where i.id=l.apparel_inventory_id and i.player_id=p_player_id for update of i;
 select coalesce(max(coalesce((c.gameplay_effects->>'racket_wear_reduction_pct')::numeric,0)*public.equipment_condition_factor_v1(i.condition)),0) into bag_protect from public.player_equipment_accessory_loadout al join public.player_equipment_inventory i on i.id=al.inventory_id and i.player_id=al.player_id join public.equipment_catalog_items c on c.id=i.catalog_item_id where al.player_id=p_player_id and al.accessory_kind='bag';
 actual_rw:=coalesce(rw,0)*(1-greatest(0,least(35,bag_protect))/100.0);actual_shw:=case when shoe_surface=v_surface then coalesce(shw,0) when shoe_surface='all' then coalesce(shw,0)*1.15 else coalesce(shw,0)*coalesce(shoe_mult,1.8) end;ra:=greatest(0,round(coalesce(rb,0)-actual_rw,2));sha:=greatest(0,round(coalesce(shb,0)-actual_shw,2));apa:=greatest(0,round(coalesce(apb,0)-coalesce(apw,0),2));
 if l.racket_inventory_id is not null then update public.player_equipment_inventory set condition=ra,updated_at=now() where id=l.racket_inventory_id and player_id=p_player_id;end if;if l.shoes_inventory_id is not null then update public.player_equipment_inventory set condition=sha,updated_at=now() where id=l.shoes_inventory_id and player_id=p_player_id;end if;if l.apparel_inventory_id is not null then update public.player_equipment_inventory set condition=apa,updated_at=now() where id=l.apparel_inventory_id and player_id=p_player_id;end if;
 for a in select al.accessory_kind,i.id inventory_id,i.condition,c.wear_per_match from public.player_equipment_accessory_loadout al join public.player_equipment_inventory i on i.id=al.inventory_id and i.player_id=al.player_id join public.equipment_catalog_items c on c.id=i.catalog_item_id where al.player_id=p_player_id for update of i loop before_acc:=before_acc||jsonb_build_object(a.accessory_kind,jsonb_build_object('inventory_id',a.inventory_id,'condition',a.condition));a_after:=greatest(0,round(a.condition-a.wear_per_match,2));update public.player_equipment_inventory set condition=a_after,updated_at=now() where id=a.inventory_id and player_id=p_player_id;after_acc:=after_acc||jsonb_build_object(a.accessory_kind,jsonb_build_object('inventory_id',a.inventory_id,'condition',a_after));end loop;
 insert into public.player_equipment_wear_events(player_id,match_id,surface,racket_before,racket_after,string_before,string_after,shoes_before,shoes_after,apparel_before,apparel_after,accessories_before,accessories_after) values(p_player_id,p_match_id,v_surface,rb,ra,null,null,shb,sha,apb,apa,before_acc,after_acc);
 return jsonb_build_object('status','applied','racket',jsonb_build_array(rb,ra),'shoes',jsonb_build_array(shb,sha),'apparel',jsonb_build_array(apb,apa),'accessories_before',before_acc,'accessories_after',after_acc,'racket_wear_applied',round(actual_rw,2),'shoe_wear_applied',round(actual_shw,2),'bag_protection_pct',round(bag_protect,2));
end; $$;
revoke all on function public.apply_equipment_match_wear_v1(uuid,uuid,text) from public,anon,authenticated;

create or replace function public.get_equipment_dashboard_v1() returns jsonb language plpgsql security definer set search_path='public' as $$
declare v_player uuid;v_balance bigint:=0;v_loadout jsonb;v_inventory jsonb;v_catalog jsonb;
begin
 select p.id into v_player from public.players p where p.owner_user_id=auth.uid() order by p.created_at desc limit 1;if v_player is null then raise exception 'Player not found.';end if;perform public.initialize_player_equipment_v1(v_player);perform public.ensure_player_career_finance_v1(v_player);select balance into v_balance from public.player_career_finance_accounts where player_id=v_player;
 select jsonb_build_object('apparel_brand',l.apparel_brand,'racket_sponsor_name',l.racket_sponsor_name,'apparel_sponsor_name',l.apparel_sponsor_name,'footwear_sponsor_name',l.footwear_sponsor_name,'racket',case when ri.id is null then null else jsonb_build_object('inventory_id',ri.id,'condition',ri.condition,'item',to_jsonb(rc)||jsonb_build_object('brand_logo_url',rb.logo_url,'technical_brand_tier',rb.tier,'technical_brand_code',rb.code,'effective_gameplay_effects',public.scale_equipment_effects_v1(rc.gameplay_effects,ri.condition))) end,'shoes',case when shi.id is null then null else jsonb_build_object('inventory_id',shi.id,'condition',shi.condition,'item',to_jsonb(shc)||jsonb_build_object('brand_logo_url',shb.logo_url,'technical_brand_tier',shb.tier,'technical_brand_code',shb.code,'effective_gameplay_effects',public.scale_equipment_effects_v1(shc.gameplay_effects,shi.condition))) end,'apparel',case when api.id is null then null else jsonb_build_object('inventory_id',api.id,'condition',api.condition,'item',to_jsonb(apc)||jsonb_build_object('brand_logo_url',apb.logo_url,'technical_brand_tier',apb.tier,'technical_brand_code',apb.code,'effective_gameplay_effects',public.scale_equipment_effects_v1(apc.gameplay_effects,api.condition))) end,'accessories',coalesce((select jsonb_agg(jsonb_build_object('accessory_kind',al.accessory_kind,'inventory_id',ai.id,'condition',ai.condition,'item',to_jsonb(ac)||jsonb_build_object('brand_logo_url',ab.logo_url,'technical_brand_tier',ab.tier,'technical_brand_code',ab.code,'effective_gameplay_effects',public.scale_equipment_effects_v1(ac.gameplay_effects,ai.condition))) order by al.accessory_kind) from public.player_equipment_accessory_loadout al join public.player_equipment_inventory ai on ai.id=al.inventory_id and ai.player_id=al.player_id join public.equipment_catalog_items ac on ac.id=ai.catalog_item_id and ac.is_active left join public.technical_sponsor_brands ab on ab.id=ac.technical_brand_id where al.player_id=l.player_id),'[]'::jsonb)) into v_loadout from public.player_equipment_loadouts l left join public.player_equipment_inventory ri on ri.id=l.racket_inventory_id and ri.player_id=l.player_id left join public.equipment_catalog_items rc on rc.id=ri.catalog_item_id and rc.is_active left join public.technical_sponsor_brands rb on rb.id=rc.technical_brand_id left join public.player_equipment_inventory shi on shi.id=l.shoes_inventory_id and shi.player_id=l.player_id left join public.equipment_catalog_items shc on shc.id=shi.catalog_item_id and shc.is_active left join public.technical_sponsor_brands shb on shb.id=shc.technical_brand_id left join public.player_equipment_inventory api on api.id=l.apparel_inventory_id and api.player_id=l.player_id left join public.equipment_catalog_items apc on apc.id=api.catalog_item_id and apc.is_active left join public.technical_sponsor_brands apb on apb.id=apc.technical_brand_id where l.player_id=v_player;
 select coalesce(jsonb_agg(jsonb_build_object('inventory_id',i.id,'condition',i.condition,'acquired_source',i.acquired_source,'acquired_absolute_day',i.acquired_absolute_day,'purchase_price_usd',i.purchase_price_usd,'is_equipped',(coalesce(i.id=l.racket_inventory_id,false) or coalesce(i.id=l.shoes_inventory_id,false) or coalesce(i.id=l.apparel_inventory_id,false) or exists(select 1 from public.player_equipment_accessory_loadout al where al.player_id=i.player_id and al.inventory_id=i.id)),'resell_supported',(i.acquired_source='purchase' and c.is_resellable),'can_sell',(i.acquired_source='purchase' and c.is_resellable and not (coalesce(i.id=l.racket_inventory_id,false) or coalesce(i.id=l.shoes_inventory_id,false) or coalesce(i.id=l.apparel_inventory_id,false) or exists(select 1 from public.player_equipment_accessory_loadout al where al.player_id=i.player_id and al.inventory_id=i.id)) and public.calculate_equipment_resale_value_v1(i.purchase_price_usd,i.condition,c.resale_modifier)>0),'sell_block_reason',case when i.acquired_source<>'purchase' then 'Starter, sponsored and reward equipment cannot be sold.' when not c.is_resellable then 'This equipment item cannot be resold.' when coalesce(i.id=l.racket_inventory_id,false) or coalesce(i.id=l.shoes_inventory_id,false) or coalesce(i.id=l.apparel_inventory_id,false) or exists(select 1 from public.player_equipment_accessory_loadout al where al.player_id=i.player_id and al.inventory_id=i.id) then 'Equip a replacement before selling this item.' when public.calculate_equipment_resale_value_v1(i.purchase_price_usd,i.condition,c.resale_modifier)<=0 then 'This equipment has no resale value.' else null end,'resale_value_usd',public.calculate_equipment_resale_value_v1(i.purchase_price_usd,i.condition,c.resale_modifier),'item',to_jsonb(c)||jsonb_build_object('brand_logo_url',b.logo_url,'technical_brand_tier',b.tier,'technical_brand_code',b.code,'effective_gameplay_effects',public.scale_equipment_effects_v1(c.gameplay_effects,i.condition))) order by c.item_type,c.sort_order,i.created_at),'[]'::jsonb) into v_inventory from public.player_equipment_inventory i join public.equipment_catalog_items c on c.id=i.catalog_item_id and c.is_active and c.item_type in ('racket','shoes','apparel','accessory') left join public.technical_sponsor_brands b on b.id=c.technical_brand_id join public.player_equipment_loadouts l on l.player_id=i.player_id where i.player_id=v_player;
 select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('brand_logo_url',b.logo_url,'technical_brand_tier',b.tier,'technical_brand_code',b.code) order by c.item_type,c.sort_order),'[]'::jsonb) into v_catalog from public.equipment_catalog_items c left join public.technical_sponsor_brands b on b.id=c.technical_brand_id where c.is_active and c.availability_status<>'unavailable' and c.item_type in ('racket','shoes','apparel','accessory');
 return jsonb_build_object('player_id',v_player,'currency','USD','balance',coalesce(v_balance,0),'loadout',coalesce(v_loadout,'{}'::jsonb),'inventory',v_inventory,'catalog',v_catalog,'resale_base_percent',65,'effects',jsonb_build_object('hard',public.get_equipment_match_modifiers_internal_v1(v_player,'hard'),'clay',public.get_equipment_match_modifiers_internal_v1(v_player,'clay'),'grass',public.get_equipment_match_modifiers_internal_v1(v_player,'grass')),'wear_rules',jsonb_build_object('racket_default',1.50,'shoes_all_court',3.68,'shoes_surface_specific',2.60,'shoes_wrong_surface',4.68,'apparel_typical',1.40,'accessory_profiles',jsonb_build_object('bag',0.35,'cap',0.70,'towel',3.00,'bottle',12.50,'dampener',2.00,'overgrip',5.00,'wristband',1.50),'condition_precision',0.01));
end; $$;
revoke all on function public.get_equipment_dashboard_v1() from public,anon;grant execute on function public.get_equipment_dashboard_v1() to authenticated;

create or replace function public.sell_equipment_item_v1(p_inventory_id uuid) returns jsonb language plpgsql security definer set search_path='public' as $$
declare v_player uuid;i public.player_equipment_inventory%rowtype;c public.equipment_catalog_items%rowtype;l public.player_equipment_loadouts%rowtype;v_resale bigint;v_abs integer;f jsonb;v_equipped boolean:=false;
begin select p.id into v_player from public.players p where p.owner_user_id=auth.uid() order by p.created_at desc limit 1;if v_player is null then raise exception 'Player not found.';end if;perform public.initialize_player_equipment_v1(v_player);select inv.* into i from public.player_equipment_inventory inv where inv.id=p_inventory_id and inv.player_id=v_player for update;if i.id is null then raise exception 'Equipment item not owned.';end if;select * into c from public.equipment_catalog_items where id=i.catalog_item_id;if c.id is null then raise exception 'Equipment definition not found.';end if;if i.acquired_source<>'purchase' then raise exception 'Starter, sponsored and reward equipment cannot be sold.';end if;if not c.is_resellable then raise exception 'This equipment item cannot be resold.';end if;select * into l from public.player_equipment_loadouts where player_id=v_player;v_equipped:=p_inventory_id=l.racket_inventory_id or p_inventory_id=l.string_inventory_id or p_inventory_id=l.shoes_inventory_id or p_inventory_id=l.apparel_inventory_id or exists(select 1 from public.player_equipment_accessory_loadout al where al.player_id=v_player and al.inventory_id=p_inventory_id);if v_equipped then raise exception 'This item is currently equipped. Equip a replacement before selling it.';end if;v_resale:=public.calculate_equipment_resale_value_v1(i.purchase_price_usd,i.condition,c.resale_modifier);if v_resale<=0 then raise exception 'This equipment has no resale value.';end if;select public.game_day_absolute_v1(d.season,d.month,d.day) into v_abs from public.get_current_game_day_internal_v1() d;f:=public.post_career_finance_transaction_v1(v_player,v_resale,'equipment',c.item_type,'Equipment sale — '||c.brand||' '||c.model,'equipment_inventory',i.id::text,'equipment-sale:'||i.id::text,jsonb_build_object('catalog_item_id',c.id,'inventory_id',i.id,'sku',c.sku,'brand',c.brand,'model',c.model,'item_type',c.item_type,'purchase_price_usd',i.purchase_price_usd,'condition',i.condition,'resale_modifier',c.resale_modifier),false,v_abs);delete from public.player_equipment_inventory where id=i.id and player_id=v_player;return jsonb_build_object('status','sold','inventory_id',i.id,'item_type',c.item_type,'sale_price_usd',v_resale,'balance',f->'balance');end; $$;
revoke all on function public.sell_equipment_item_v1(uuid) from public,anon;grant execute on function public.sell_equipment_item_v1(uuid) to authenticated;
revoke all on function public.purchase_equipment_item_v2(uuid,text) from public,anon;grant execute on function public.purchase_equipment_item_v2(uuid,text) to authenticated;

do $$ declare r record;begin for r in select id from public.players where owner_user_id is not null loop perform public.initialize_player_equipment_v1(r.id);end loop;end; $$;

comment on table public.player_equipment_accessory_loadout is 'One equipped accessory per accessory kind; each points to the authoritative player-owned equipment instance.';
comment on column public.equipment_catalog_items.gameplay_effects is 'Small per-item percentage effects. Effective values are scaled by the owned item condition.';
comment on column public.equipment_catalog_items.wear_per_match is 'Base condition percentage points lost per completed match while equipped.';
